-- Seed explicito del dataset de Mike. Los historicalWorkoutDrafts no se insertan:
-- carecen de startedAt y de series exactas segun el contrato de importacion.

SELECT 1, 'mike@example.invalid', 'Mike', '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM users WHERE id = 1);

WITH types(code, name, unit, description) AS (VALUES
  ('weight_kg', 'Weight', 'kg', NULL),
  ('bmi', 'Body mass index', NULL, NULL),
  ('body_fat_pct', 'Body fat', '%', NULL),
  ('fat_mass_kg', 'Fat mass', 'kg', NULL),
  ('muscle_mass_kg', 'Muscle mass', 'kg', NULL),
  ('skeletal_muscle_mass_kg', 'Skeletal muscle mass', 'kg', NULL),
  ('water_pct', 'Body water', '%', NULL),
  ('protein_pct', 'Protein', '%', NULL),
  ('bone_mass_kg', 'Bone mass', 'kg', NULL),
  ('subcutaneous_fat_pct', 'Subcutaneous fat', '%', NULL),
  ('visceral_fat', 'Visceral fat', NULL, NULL),
  ('basal_metabolism_kcal', 'Basal metabolism', 'kcal/day', NULL),
  ('resting_heart_rate_bpm', 'Resting heart rate', 'bpm', NULL)
), missing AS (
  SELECT types.* FROM types
  WHERE NOT EXISTS (SELECT 1 FROM body_metric_types WHERE code = types.code)
), numbered AS (
  SELECT *, ROW_NUMBER() OVER (ORDER BY code) AS offset FROM missing
), maximum AS (SELECT COALESCE(MAX(id), 0) AS id FROM body_metric_types)
SELECT maximum.id + numbered.offset, code, name, unit, description
FROM numbered CROSS JOIN maximum;

WITH seed_exercises(slug, name, movement_pattern, equipment, technique_notes, safety_notes) AS (VALUES
  ('bike-or-elliptical', 'Bicicleta o elíptica', 'Calentamiento', 'Bicicleta o elíptica', 'Progresivo, sin fatiga', 'Sin impacto; comprobar la rodilla'),
  ('walking-treadmill', 'Cinta andando', 'Calentamiento', 'Cinta', 'Ritmo progresivo y conversacional', 'Valorar la rodilla'),
  ('goblet-squat-to-bench', 'Goblet squat a banco', 'Dominante de rodilla', 'Mancuerna y banco', 'Controlar bajada, rango estable y rodillas alineadas', 'Parar ante dolor, inestabilidad o bloqueo'),
  ('neutral-grip-lat-pulldown', 'Jalón al pecho agarre neutro', 'Tracción vertical', 'Polea', 'Pecho alto, hombros bajos y nunca tras la nuca', 'Usar recorrido cómodo y sin dolor acromioclavicular'),
  ('dumbbell-romanian-deadlift', 'Peso muerto rumano con mancuernas', 'Bisagra de cadera', 'Mancuernas', 'Cadera atrás, espalda neutra y flexión moderada de rodilla', 'La tensión debe sentirse en isquios, no en la zona lumbar'),
  ('seated-cable-row', 'Remo sentado en polea', 'Tracción horizontal', 'Polea', 'Sin balanceo; pausa breve juntando escápulas', 'No elevar los hombros'),
  ('neutral-grip-chest-press', 'Press de pecho en máquina, agarre neutro', 'Empuje horizontal', 'Máquina', 'Codos a 30-45 grados y recorrido controlado', 'Reducir recorrido o sustituir ante molestia'),
  ('pallof-press', 'Pallof press', 'Core anti-rotación', 'Polea o banda', 'Mantener el tronco estable sin girar', 'Sin dolor lumbar'),
  ('half-kneeling-landmine-press', 'Press unilateral en landmine, medio arrodillado', 'Empuje vertical', 'Barra landmine', 'Empujar hacia arriba y delante en el plano escapular', 'No encoger el hombro ni forzar el final del recorrido'),
  ('easy-stationary-bike', 'Bicicleta suave', 'Cardio', 'Bicicleta', 'Ritmo conversacional', 'Omitir si aumenta la sensación en la rodilla'),
  ('hip-thrust-or-glute-bridge', 'Hip thrust o puente de glúteos', 'Bisagra de cadera', 'Banco y barra o máquina', 'Pausa breve arriba', 'No hiperextender la zona lumbar'),
  ('chest-supported-row', 'Remo con pecho apoyado', 'Tracción horizontal', 'Máquina o banco inclinado', 'Cuello neutro, hombros bajos y sin impulso', 'No encoger los hombros'),
  ('supported-low-step-up', 'Step-up bajo con apoyo', 'Dominante de rodilla unilateral', 'Cajón bajo', 'Controlar la bajada; se permite apoyo', 'Sustituir si aumenta la sensación rara en la rodilla'),
  ('incline-push-up', 'Flexiones inclinadas', 'Empuje inclinado', 'Banco o soporte', 'Cuerpo alineado y codos a 30-45 grados', 'Elegir una altura que permita control escapular sin dolor'),
  ('dead-bug', 'Dead bug', 'Core anti-extensión', 'Peso corporal', 'Zona lumbar apoyada y movimiento lento', 'Reducir el rango si se arquea la espalda'),
  ('leg-press-comfortable-range', 'Prensa con recorrido cómodo', 'Dominante de rodilla', 'Máquina de prensa', 'Rodillas alineadas; controlar bajada y no bloquear al extender', 'Usar recorrido cómodo y sin dolor'),
  ('converging-chest-press', 'Press de pecho convergente', 'Empuje horizontal', 'Máquina convergente', 'Codos a 30-45 grados y recorrido controlado', 'Sin dolor ni pinzamiento'),
  ('side-plank', 'Plancha lateral', 'Core lateral', 'Peso corporal', 'Cuerpo alineado y cadera alta sin girar', 'Apoyo cómodo para el hombro; apoyar rodillas si se pierde postura'),
  ('suitcase-carry', 'Suitcase carry', 'Carry y core lateral', 'Mancuerna', 'Caminar estable sin inclinar el tronco', 'No encoger el hombro'),
  ('standard-push-up', 'Flexiones normales', 'Empuje horizontal', 'Peso corporal', 'Cuerpo alineado y codos a 30-45 grados', 'Reducir el rango si aparece molestia'),
  ('military-press', 'Press militar', 'Empuje vertical', 'Máquina o mancuernas', 'Recorrido controlado sin forzar el final', 'Vigilar especialmente la articulación acromioclavicular')
)
SELECT (SELECT COALESCE(MAX(id), 0) FROM exercises) + ROW_NUMBER() OVER (ORDER BY seed.slug), seed.slug, seed.name, seed.movement_pattern, seed.equipment, seed.technique_notes, seed.safety_notes, 1, '2026-08-12T00:00:00.000Z', '2026-08-12T00:00:00.000Z'
FROM seed_exercises AS seed
WHERE NOT EXISTS (SELECT 1 FROM exercises WHERE exercises.slug = seed.slug);

-- The catalog INSERT above allocates IDs from the current catalog while retaining
-- the source slug as the stable reference used by the routine rows below.

SELECT ROW_NUMBER() OVER (ORDER BY metric.code), 1, metric.id, metric_values.metric_value
FROM body_metric_types AS metric
JOIN (SELECT 'weight_kg' AS code, 103.3 AS metric_value UNION ALL SELECT 'bmi', 28.6 UNION ALL SELECT 'body_fat_pct', 27.6 UNION ALL SELECT 'fat_mass_kg', 28.5 UNION ALL SELECT 'muscle_mass_kg', 70.6 UNION ALL SELECT 'skeletal_muscle_mass_kg', 55.4 UNION ALL SELECT 'water_pct', 53.6 UNION ALL SELECT 'protein_pct', 13.9 UNION ALL SELECT 'bone_mass_kg', 4.2 UNION ALL SELECT 'subcutaneous_fat_pct', 24.1 UNION ALL SELECT 'visceral_fat', 13 UNION ALL SELECT 'basal_metabolism_kcal', 1986 UNION ALL SELECT 'resting_heart_rate_bpm', 65) AS metric_values ON metric_values.code = metric.code
WHERE NOT EXISTS (SELECT 1 FROM body_measurements WHERE id = 1);

SELECT 1, 1, '2026-08-03T22:00:00.000Z', 'Báscula de bioimpedancia', 'Medición inicial real. Las métricas de composición son estimaciones y se usarán principalmente para seguir tendencias.', '2026-08-12T00:00:00.000Z'
WHERE NOT EXISTS (SELECT 1 FROM body_measurements WHERE id = 1);

-- Rutinas y versiones iniciales.

UPDATE routine_versions SET is_sealed=1 WHERE id=1 AND is_sealed=0;
UPDATE routines SET pending_version_number=NULL,protocol_state=0,current_version_is_sealed=1 WHERE id=1 AND protocol_state=1;

UPDATE routine_versions SET is_sealed=1 WHERE id=2 AND is_sealed=0;
UPDATE routines SET pending_version_number=NULL,protocol_state=0,current_version_is_sealed=1 WHERE id=2 AND protocol_state=1;

UPDATE routine_versions SET is_sealed=1 WHERE id=3 AND is_sealed=0;
UPDATE routines SET pending_version_number=NULL,protocol_state=0,current_version_is_sealed=1 WHERE id=3 AND protocol_state=1;
